import sys
from collections import defaultdict, deque

input = sys.stdin.read
data = input().split()

index = 0

def read_int():
    global index
    value = int(data[index])
    index += 1
    return value

def read_ints():
    global index
    values = []
    while index < len(data) and data[index].isdigit():
        values.append(int(data[index]))
        index += 1
    return values

def solve(n, m, edges):
    adj = defaultdict(list)
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    degree = [len(adj[i]) for i in range(1, n + 1)]

    for subset in range(1, 1 << n):
        stolen = []
        for i in range(n):
            if subset & (1 << i):
                stolen.append(i + 1)

        if len(stolen) == 0:
            continue

        new_degree = degree[:]
        for v in stolen:
            for u in adj[v]:
                new_degree[u - 1] -= 1

        for v in range(1, n + 1):
            if new_degree[v - 1] % 3 != degree[v - 1] % 3:
                break
        else:
            return True, stolen

    return False, []

def main():
    t = read_int()
    index = 0
    for _ in range(t):
        n = read_int()
        m = read_int()
        edges = []
